use std::fs
use std::collections::HashMap

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut totals: HashMap<string, int> = HashMap::new()
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut acts: HashMap<string, int> = HashMap::new()
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            if line.trim().len() > 0 || true {
                bad += 1
            }
            continue
        }
        let user = parts[0]
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        totals.insert(user, totals.get(user).unwrap_or(0) + secs)
        counts.insert(user, counts.get(user).unwrap_or(0) + 1)
        let key = "${user} ${parts[1]}"
        acts.insert(key, acts.get(key).unwrap_or(0) + 1)
    }
    let mut users: Vec<string> = []
    for k in totals.keys() {
        users.push(k)
    }
    users.sort()
    let mut tvals: Vec<int> = []
    for u in users {
        tvals.push(totals.get(u).unwrap_or(0))
    }
    let n: int = users.len() as int
    let mut order: Vec<int> = []
    let mut i = 0
    while i < n {
        order.push(i)
        i += 1
    }
    // stable insertion sort by total descending (users already name-sorted)
    let mut a = 1
    while a < n {
        let mut j = a
        while j > 0 && tvals[order[j - 1] as usize] < tvals[order[j] as usize] {
            let t = order[j]
            order[j] = order[j - 1]
            order[j - 1] = t
            j -= 1
        }
        a += 1
    }
    let mut sorted: Vec<string> = []
    for idx in order {
        sorted.push(users[idx])
    }
    users = sorted
    for u in users {
        let mut best = ""
        let mut bc = 0
        for k in acts.keys() {
            let ps: Vec<string> = k.split(" ").collect()
            if ps[0] == u {
                let c: int = acts.get(k).unwrap_or(0) + 0
                if c > bc || (c == bc && ps[1] < best) {
                    bc = c
                    best = ps[1]
                }
            }
        }
        println("${u} ${counts.get(u).unwrap_or(0)} ${totals.get(u).unwrap_or(0)} ${best}")
    }
    println("malformed: ${bad}")
}

